from pathlib import Path
import json
from datetime import datetime,timezone

root=Path(__file__).resolve().parent
read=lambda name:json.loads((root/name).read_text(encoding='utf-8'))
results=read('results.json')
start=read('evidence/START-001-independent-verification.json')
assert start['mark_redo_reopened_exact'] and start['saved_project_reopened_exact'] and start['returning_did_not_auto_resume']
results['cases']['START-001']=dict(status='Pass',variants_executed='Fresh http://127.0.0.1:8089 origin with no prior preferences; normal Brushes and Blue controls; native gesture; Undo/Redo; actual project save and fresh-tab chooser reopen. Saved session reloaded to expose its real recovery suggestion, then green drawing performed without choosing Resume.',criteria_observations='Ready white 960x640 paper appears in basic mode without an account or tutorial dialog. The selected Brushes tile and checked Blue swatch are visible. A single gesture draws blue and Undo is enabled. Undo restores exact white pixels; Redo and actual reopen restore the exact blue image and project. The pending recovery suggestion leaves fresh paper usable; green input does not silently resume the old blue picture.',independent_oracle='Pillow 12.3.0 exact RGBA and known colour centres; full project JSON identity; actual UI screenshots and fresh-origin setup',evidence_paths='evidence/START-001-independent-verification.json; evidence/START-001-fresh-origin-ui.jpg; evidence/START-001-first-mark-ui.jpg; evidence/START-001-first-mark.retropaint; evidence/START-001-reopened.retropaint; evidence/START-001-returning-ready-ui.jpg; evidence/START-001-returning-still-usable-ui.jpg; ui-events-current.jsonl',defect_or_blocker='None. Recovery suggestion is scoped to a reloaded session; the initial new-tab precondition was corrected before execution. Long control transport time is not an application performance measurement.')
photo=read('evidence/PHOTO-004-independent-verification.json')
assert len(photo['rows'])==3 and all(r['outstanding_preview_observed'] and r['saved_project_exact'] and r['full_size_rgba_exact'] for r in photo['rows']) and photo['actual_file_save_and_fresh_tab_reopen_exact']
results['cases']['PHOTO-004']=dict(status='Pass',variants_executed='User-owned Laukka sunset.jpg, 3896x2586; saved Exposure +1 and Brightness +7; distinct green paint on a second sheet. Reopened experiments at Exposure -4 and Brightness -100 cancelled by Cancel, Close and focused-control Escape while Updating preview was visible. Actual project and PNG downloaded after every branch, followed by a fresh-tab native chooser reopen.',criteria_observations='Every branch preserves the complete saved recipe, original image bytes, layer order/visibility/active target and the neighbouring paint sheet. All full-size exports are pixel exact after the outstanding previews have had time to finish. Reopening the lab restores +1/+7; fresh project reopen retains exact JSON and rendered pixels. The neighbour has independently checked green RGBA 67,160,71,255 and clear untouched pixels.',independent_oracle='Pillow 12.3.0 exact full-size RGBA; full saved project JSON identity; retained original source PNG; observed outstanding preview before each cancellation',evidence_paths='evidence/PHOTO-004-independent-verification.json; evidence/PHOTO-004-saved-before.retropaint; evidence/PHOTO-004-cancel-inflight.json; evidence/PHOTO-004-close-inflight.json; evidence/PHOTO-004-escape-inflight.json; evidence/PHOTO-004-reopened.retropaint; evidence/PHOTO-004-reopened-ready-ui.jpg; ui-events-current.jsonl',defect_or_blocker='None. A non-focusable-panel Escape delivery attempt was discarded; actual Escape was delivered from the focused Exposure slider and verified. An initial loading snapshot was retained separately and not treated as a completed reopen.')
results['cases']['PHOTO-001']=dict(status='Partial',variants_executed='Actual Photo lab Open photo chooser on desktop and 320x568 frame, using supplied Laukka sunset.jpg, 3896x2586.',criteria_observations='The supported JPEG becomes Layer 1 and Photo lab opens with Light / Exposure & contrast as its current editing context. Original decoded pixels agree with Pillow within 1/255 and embedded source/export pixels are exact. A deliberately hidden old target and a non-default remembered category have not yet been exercised. Native picker Cancel remains unverified.',independent_oracle='Pillow 12.3.0 and actual UI dimensions/target; preserved real source bytes and hashes',evidence_paths='evidence/PHOTO-001-Laukka-opened-ui.jpg; evidence/PHOTO-source-Laukka.retropaint; evidence/PHOTO-source-Laukka.png; evidence/PHOTO-002-independent-verification.json; fixtures/import-manifest.json; evidence/PHONE-frame-download-limitation.txt',defect_or_blocker='Remaining target/context variants pending. Native chooser cancellation is not exposed by this browser-control session; no synthetic cancel is counted.')
navigation=read('evidence/PHOTO-002-independent-verification.json')
assert navigation['desktop_groups']==15 and navigation['after_navigation_project_and_rgba_exact'] and navigation['actual_file_save_and_fresh_tab_reopen_exact']
results['cases']['PHOTO-002']=dict(status='Partial',variants_executed='All six categories and all 15 desktop groups through the real controls, on the supplied 3896x2586 natural photo. Saved Exposure +1 / Brightness +7; returned to their group after all navigation; actual file save/reopen and independent full-size comparison.',criteria_observations='All rendered control rectangles are inside the 1280x720 viewport. Both non-default values survive category/group changes. Cancelling navigation preserves exact saved JSON and full-size RGBA, including on actual fresh-tab reopen. The short-screen combined-selector branch remains pending.',independent_oracle='DOM-visible control values/rectangles and per-group screenshots; Pillow 12.3.0 full-size RGBA; exact JSON from actual project downloads',evidence_paths='evidence/PHOTO-002-desktop-groups.json; evidence/PHOTO-002-independent-verification.json; evidence/PHOTO-002-before-navigation.retropaint; evidence/PHOTO-002-after-navigation.retropaint; evidence/PHOTO-002-reopened.retropaint; evidence/PHOTO-002-return-to-light-ui.jpg; ui-events-current.jsonl',defect_or_blocker='Short-screen combined-selector workflow still to execute. Frame chooser imports work, but frame downloads report ready without captured output bytes; no frame persistence pass is claimed.')
results['updated_at']=datetime.now(timezone.utc).isoformat()
(root/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('Recorded two verified Pass outcomes and two Partial photo workflows')
